{
  "overall_decision": "pass",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0001",
          "reason": "Office-and-authority baseline only; it defines Bolsonaro's decision space but does not show any personal nuclear-risk act."
        },
        {
          "evidence_id": "E0011",
          "reason": "Inherited treaty status and zone membership are contextual constraints, not Bolsonaro-specific conduct."
        }
      ],
      "material_gaps": [
        {
          "gap": "No direct 2022 Bolsonaro-specific nuclear command, crisis, or near-use choice is evidenced.",
          "lenses": ["1B.2", "1B.3", "1B.8", "1B.9"],
          "best_source_or_query_direction": "2022 GSI, Itamaraty, ABACC, and presidential-security records on nuclear-safety decisions, incident handling, and any crisis communications.",
          "why_it_matters": "It keeps the chapter correctly limited to exposure and avoids over-crediting treaty posture or institutional baseline as personal restraint."
        }
      ],
      "reason": "The package fairly separates Brazil's inherited nuclear-safety architecture from Bolsonaro's 2022 actions. It shows limited exposure, formal safeguards, and anti-proliferation diplomacy, while not pretending there was a direct nuclear command crisis to score."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0016",
          "reason": "Brazil's condemnation of North Korea is lawful-security context, not Bolsonaro's own conflict conduct."
        }
      ],
      "material_gaps": [],
      "reason": "The package presents the mixed 2022 conduct fairly: pro-Ukraine voting and humanitarian measures sit alongside Bolsonaro's Russia/neutrality rhetoric and later abstentions. It preserves contrary evidence and does not overread Brazil's UN posture as a clean personal-peace record."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0043",
          "reason": "The roadblock reporting is allegation-based and should not be treated as a final finding of Bolsonaro's command responsibility."
        }
      ],
      "material_gaps": [],
      "reason": "This chapter is well supported by direct incitement, gun-liberalization, journalist-hostility, Indigenous-rights, and election-risk evidence, with clear contrary evidence and institutional pushback. The package keeps allegations and legal findings distinct enough for fair use."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0047",
          "reason": "The election result is an institutional outcome and transition marker, not Bolsonaro conduct."
        }
      ],
      "material_gaps": [],
      "reason": "The dossier cleanly covers manipulation, misuse of official imagery, fraud rhetoric, and electoral scrutiny, while also preserving the fact that the 2022 election remained competitive. It distinguishes institutional resilience from Bolsonaro's own conduct."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0052",
          "reason": "The central-bank report is macro context from an autonomous institution; it should not be read as direct presidential performance evidence."
        }
      ],
      "material_gaps": [],
      "reason": "The package fairly separates macro outcomes from presidential agency. It includes direct policy choices, emergency transfers, and staffing decisions, while also showing the role of external shocks, commodity revenues, and an autonomous central bank."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0073",
          "reason": "This is a retrospective outcome summary that mixes labor-market rebound with transfer policy; it should be treated as partial attribution, not pure Bolsonaro causation."
        }
      ],
      "material_gaps": [],
      "reason": "The chapter is fairly presented as a mixed social-policy record: real transfer expansion and targeting infrastructure on one side, but weak service-quality and deprivation evidence on the other. The package keeps coverage and durability distinct from simple output counts."
    },
    {
      "chapter_id": "7B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0087",
          "reason": "This is overlapping Reuters coverage of the same Petrobras pressure episode already captured elsewhere; it should corroborate, not count as a separate event."
        },
        {
          "evidence_id": "E0089",
          "reason": "Public asset disclosure shows reported holdings, not hidden wealth or illicit enrichment."
        },
        {
          "evidence_id": "E0090",
          "reason": "The family-property story is allegation-level, spans relatives and years, and is not a finding of office-based self-dealing."
        },
        {
          "evidence_id": "E0091",
          "reason": "The Michelle Bolsonaro payments story is an unresolved investigation and should not be treated as a proved offense."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct forensic proof of hidden self-dealing or office-linked family enrichment remains thin.",
          "lenses": ["7B.3", "7B.4", "7B.7"],
          "best_source_or_query_direction": "TSE, CGU, TCU, asset-declaration audits, procurement records, and any court or inquiry findings on campaign finance or family-linked payments.",
          "why_it_matters": "It prevents allegations from being upgraded into findings and bounds the integrity assessment."
        }
      ],
      "reason": "The package is usable because it combines Bolsonaro-specific falsehood patterns, scrutiny, and politicized use of state power with clearly labeled allegations and unresolved inquiries. The main weakness is not evidence absence overall, but that some self-dealing claims remain non-final and must stay non-decisive."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0094",
          "reason": "This later TSE ruling is retrospective confirmation of a 2022 act; it should not be treated as contemporaneous competence evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "Broader durable non-electoral program execution is thinner than the campaign-and-power-retention record.",
          "lenses": ["8B.2", "8B.7", "8B.10"],
          "best_source_or_query_direction": "Cabinet and budget-execution records, ministry performance reports, and post-2022 outcome evaluations for priority policy areas.",
          "why_it_matters": "It avoids inferring broad competence from tactical election-year mobilization or one-off state-machine uses."
        }
      ],
      "reason": "The package gives a coherent revealed-program picture centered on reelection, coalition control, and campaign-state coordination, and it shows concrete action in that direction. It is also honest about the fact that the strongest evidence is tactical rather than durable, which is exactly the right boundary for this chapter."
    }
  ]
}
